CREATE TABLE er_account (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, login_account VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, employee_name VARCHAR(100) NOT NULL, role VARCHAR(32) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, failed_attempts INT NOT NULL DEFAULT 0, locked_until TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE er_audit_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, actor_account VARCHAR(100), action VARCHAR(80) NOT NULL, target_type VARCHAR(80), target_id VARCHAR(80), summary VARCHAR(500), created_at TIMESTAMP NOT NULL);
CREATE TABLE er_enterprise_profile (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, company_name VARCHAR(255) NOT NULL, unified_credit_code VARCHAR(32) NOT NULL UNIQUE, subject_type VARCHAR(32) NOT NULL DEFAULT 'OTHER', source VARCHAR(32) NOT NULL, monitoring_enabled BOOLEAN NOT NULL DEFAULT TRUE, collection_status VARCHAR(32) NOT NULL DEFAULT 'UNSCANNED', latest_success_at TIMESTAMP NULL, latest_failure_at TIMESTAMP NULL, latest_failure_code VARCHAR(80), latest_failure_message VARCHAR(500), risk_score DECIMAL(8,2), risk_level VARCHAR(32), coverage DECIMAL(8,4), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE er_collection_run (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, status VARCHAR(24) NOT NULL, total_count INT NOT NULL, success_count INT NOT NULL DEFAULT 0, partial_count INT NOT NULL DEFAULT 0, failure_count INT NOT NULL DEFAULT 0, created_by VARCHAR(100), created_at TIMESTAMP NOT NULL, completed_at TIMESTAMP NULL);
CREATE TABLE er_collection_attempt (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, run_id BIGINT NULL, status VARCHAR(24) NOT NULL, attempt_no INT NOT NULL, retry_count INT NOT NULL DEFAULT 0, heartbeat_at TIMESTAMP NULL, error_code VARCHAR(80), error_message VARCHAR(500), started_at TIMESTAMP NOT NULL, finished_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL, CONSTRAINT fk_attempt_profile FOREIGN KEY(profile_id) REFERENCES er_enterprise_profile(id), CONSTRAINT uq_active_attempt UNIQUE(profile_id,status));
CREATE TABLE er_capability_result (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, attempt_id BIGINT NOT NULL, capability_code VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, hit BOOLEAN NULL, record_count INT NULL, normalized_json CLOB, error_code VARCHAR(80), error_message VARCHAR(500), collected_at TIMESTAMP NULL, CONSTRAINT fk_cap_attempt FOREIGN KEY(attempt_id) REFERENCES er_collection_attempt(id), CONSTRAINT uq_cap_attempt UNIQUE(attempt_id,capability_code));
CREATE TABLE er_risk_model_factor (model_type VARCHAR(32) NOT NULL, factor_code VARCHAR(64) NOT NULL, factor_name VARCHAR(100) NOT NULL, weight DECIMAL(8,4) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, version_no INT NOT NULL DEFAULT 1, updated_at TIMESTAMP NOT NULL, PRIMARY KEY(model_type,factor_code));
CREATE TABLE er_risk_score (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, model_type VARCHAR(32) NOT NULL, model_version INT NOT NULL, score DECIMAL(8,2), risk_level VARCHAR(32) NOT NULL, coverage DECIMAL(8,4), evidence_json CLOB NOT NULL, scored_at TIMESTAMP NOT NULL, CONSTRAINT fk_score_profile FOREIGN KEY(profile_id) REFERENCES er_enterprise_profile(id));
CREATE TABLE er_tianyancha_key (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, ciphertext CLOB NOT NULL, masked_key VARCHAR(120) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, daily_limit INT NOT NULL DEFAULT 600, usage_date DATE NULL, usage_count INT NOT NULL DEFAULT 0, last_used_at TIMESTAMP NULL, failure_reason VARCHAR(255), version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE er_risk_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, score_id BIGINT NOT NULL, risk_level VARCHAR(32) NOT NULL, status VARCHAR(24) NOT NULL, evidence_json CLOB NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE er_work_order (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, profile_id BIGINT NOT NULL, event_id BIGINT NOT NULL, status VARCHAR(24) NOT NULL, note VARCHAR(1000), handled_by VARCHAR(100), handled_at TIMESTAMP NULL, created_at TIMESTAMP NOT NULL);

